<template><section class="page-view"><div class="page-title-row"><div><h1>搜索结果</h1><p v-if="keyword">“{{keyword}}”</p></div></div><div v-if="loading" class="video-grid"><div v-for="n in 20" :key="n" class="video-card skeleton-card"><div class="thumb skeleton"></div><div class="line skeleton"></div><div class="line short skeleton"></div></div></div><div v-else-if="videos.length" class="video-grid"><article v-for="item in videos" :key="item.id" class="video-card" @click="open(item.id)"><div class="thumb"><img :src="item.poster||fallback" :alt="item.title" loading="lazy" @error="e=>e.target.src=fallback"><span class="badge">{{item.updateTime||''}}</span><span class="duration">{{item.duration||'HD'}}</span><button class="play" aria-label="打开">▶</button></div><h3>{{item.title}}</h3><div class="stats"><span>◉ {{formatViews(item.views)}}</span><span class="score">★ {{item.score||'—'}}</span></div></article></div><div v-else class="empty">{{keyword?'没有找到相关内容':'请输入搜索关键词'}}</div><div v-if="pageCount>1" class="pagination"><button :disabled="page<=1" @click="go(page-1)">‹</button><button v-for="n in pages" :key="n" :class="{current:n===page}" @click="go(n)">{{n}}</button><button :disabled="page>=pageCount" @click="go(page+1)">›</button></div></section></template>
<script setup>import{computed,ref,watch}from'vue';import{useRoute,useRouter}from'vue-router';import{searchVideos}from'../api/vod';const route=useRoute(),router=useRouter(),videos=ref([]),loading=ref(false),page=ref(1),pageCount=ref(1),fallback='/fallback.svg';let token=0;const keyword=computed(()=>String(route.query.wd||'').trim().slice(0,100)),pages=computed(()=>{const o=[],s=Math.max(1,Math.min(page.value-2,pageCount.value-4));for(let i=s;i<=Math.min(pageCount.value,s+4);i++)o.push(i);return o});function formatViews(v){const n=Number(v)||0;return n>999999?`${(n/1000000).toFixed(1)}M`:n>999?`${(n/1000).toFixed(1)}K`:String(n)}async function load(){const t=++token;if(!keyword.value){videos.value=[];pageCount.value=1;loading.value=false;return}loading.value=true;try{const r=await searchVideos(keyword.value,page.value,20);if(t!==token)return;videos.value=r.list;pageCount.value=Math.max(1,r.pageCount||1)}catch{if(t===token)videos.value=[]}finally{if(t===token)loading.value=false}}function go(n){const next=Math.max(1,Math.min(Number(n)||1,pageCount.value));if(next!==page.value)router.push({query:{...route.query,pg:next}})}function open(id){if(id)router.push(`/play/${id}`)}watch([()=>route.query.wd,()=>route.query.pg],()=>{const n=Number(route.query.pg);page.value=Number.isFinite(n)&&n>0?Math.min(Math.trunc(n),100000):1;load()},{immediate:true})</script>